import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.CNQbXYGB.js";const p=JSON.parse('{"title":"BW100 / gfx936 基线档案","description":"","frontmatter":{},"headers":[],"relativePath":"baselines/bw100-gfx936.md","filePath":"baselines/bw100-gfx936.md"}'),i={name:"baselines/bw100-gfx936.md"};function o(s,t,c,h,l,n){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="bw100-gfx936-基线档案" tabindex="-1">BW100 / gfx936 基线档案 <a class="header-anchor" href="#bw100-gfx936-基线档案" aria-label="Permalink to &quot;BW100 / gfx936 基线档案&quot;">​</a></h1><p>本档案记录 <strong>2026-11-18</strong> 在单张 BW100 上复测的 E01、E06、E07 和 E09。数据可以作为之后重复同一套探针的对照。<a href="./../labs/">实验索引</a></p><p><a href="/dcu-microarch-guide/data/bw100-20261118.zip">下载本轮原始数据与 ISA</a> · <a href="/dcu-microarch-guide/data/bw100-20261118/environment.txt">环境记录</a> · <a href="/dcu-microarch-guide/data/bw100-20261118/source-sha256-lf.txt">源码 SHA-256（LF）</a></p><h2 id="环境与观测口径" tabindex="-1">环境与观测口径 <a class="header-anchor" href="#环境与观测口径" aria-label="Permalink to &quot;环境与观测口径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>条目</th><th>当前记录</th></tr></thead><tbody><tr><td>运行时报告</td><td>设备 / 架构</td><td>BW100 / <code>gfx936:sramecc+:xnack-</code></td></tr><tr><td>运行时报告</td><td>CU 数 / L2 容量</td><td>64 CU / <code>8388608 B</code>（8 MiB）</td></tr><tr><td>已验证的软件栈</td><td>编译器 / DTK</td><td>DCC 25.10.0-0（clang 17.0.0）/ DTK 26.04</td></tr><tr><td>已验证的软件栈</td><td>设备驱动</td><td>6.3.31-V1.5.7，同一运行容器中于复测后通过 <code>rocm-smi --showdriverversion</code> 查询</td></tr><tr><td>已验证的软件栈</td><td>框架</td><td>PyTorch 2.5.1 / Triton 3.1.0</td></tr><tr><td>微基准结果</td><td><a href="./../labs/lab01-memory-coalescing.html">E01 · 向量拷贝</a></td><td>1367.01 GB/s，按逻辑 256 MiB 读及 256 MiB 写和无 profiler 计时折算</td></tr><tr><td>微基准结果</td><td><a href="./../labs/lab08-memory-latency-ladder.html">E06 · 依赖加载延迟</a></td><td>64 B 间距下，标量路径在 16–24 KiB 转折，向量路径在 32–48 KiB 转折</td></tr><tr><td>微基准结果</td><td><a href="./../labs/lab09-mmac-builtin-and-valu.html">E07 · MMAC 指令吞吐</a></td><td>333.49 TFLOPS，<code>16×16×16</code> MMAC，FP16 输入、FP32 累加</td></tr><tr><td>算子结果</td><td><a href="./../labs/lab07-triton-gemm-vs-rocblas.html">E09 · GEMM</a></td><td>FP16 <code>4096³</code>，PyTorch → rocBLAS 257.08 TFLOPS，本轮最快 Triton 97.33 TFLOPS</td></tr><tr><td>机制假设</td><td>E06 大工作集台阶</td><td>随机依赖链的缓存复用在 8–16 MiB 附近下降。精确缓存组织和 TLB 贡献待专项验证</td></tr></tbody></table><p>设备属性由 HIP/PyTorch 报告。对于缓存组织、指令语义和计数器定义，后续引用对应 DTK 版本的手册条目或相关架构资料。SCLK 快照采于运行前后，基线采用设备默认动态时钟。</p><h2 id="复跑基线" tabindex="-1">复跑基线 <a class="header-anchor" href="#复跑基线" aria-label="Permalink to &quot;复跑基线&quot;">​</a></h2><p>在有 BW100、DTK、PyTorch 与 Triton 的 Linux 环境，从仓库根目录执行。使用新目录，确保每次输出独立。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments/run_bw100_baseline.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gfx936</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bw100-repeat</span></span></code></pre></div><table tabindex="0"><thead><tr><th>文件</th><th>可核对的内容</th></tr></thead><tbody><tr><td><code>environment.txt</code>、<code>source-sha256.txt</code></td><td>采集时间、设备、工具链和送入容器的源文件校验值</td></tr><tr><td><code>e01.csv</code> 与设备 ISA</td><td>所有映射校验状态和逐轮有效拷贝带宽</td></tr><tr><td><code>e06-*.csv</code>、<code>e06-*-summary.txt</code> 与设备 ISA</td><td>尺寸、种子、间距、加载路径、时钟读数与独立 PMC</td></tr><tr><td><code>e07.txt</code> 与设备 ISA</td><td>指令吞吐与依赖链计时</td></tr><tr><td><code>e09-*.json</code>、<code>e09-*.s</code>、<code>e09-*-pmc.csv</code></td><td>按配置 ID 对应的计时、正确性、Triton ISA 和独立 PMC。rocBLAS 通过实际 dispatch 名称识别</td></tr></tbody></table><p>公开版 ISA 已清理本机路径及编译器内部地址。归档保留了采集时的文件 SHA-256；跨 Windows 与 Linux 检出时可用 LF 归一化清单比对。其他实验的历史记录和复测状态见 <a href="./../labs/">实验索引</a>。</p><h2 id="跨代复测规则" tabindex="-1">跨代复测规则 <a class="header-anchor" href="#跨代复测规则" aria-label="Permalink to &quot;跨代复测规则&quot;">​</a></h2><ul><li>保持形状、dtype、计时位置、codegen 参数、正确性阈值及样本统计方式一致。设备、驱动、DTK、频率策略、容器或框架改动分别记入环境记录。</li><li>同一版本的 PMC 才直接比较原始计数。跨架构先对齐指标定义、单位与范围，再计算按指令、dispatch 或工作量归一化的值。</li><li>新硬件和工具链同时升级时，记录组合差异。若两张卡都支持同一 DTK，再用同版工具链做跨硬件对照，条件允许时再补旧卡切换 DTK 的对照。</li></ul>',13)])])}const m=d(i,[["render",o]]);export{p as __pageData,m as default};
